import{_ as a,o as t,c as o,a5 as d}from"./chunks/framework.DJo0M80U.js";const f=JSON.parse('{"title":"反向代理","description":"","frontmatter":{"title":"反向代理","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","构建运维","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第七部分：构建与运维/03-Nginx/反向代理.md","filePath":"posts/java快速入门/第七部分：构建与运维/03-Nginx/反向代理.md"}'),c={name:"posts/java快速入门/第七部分：构建与运维/03-Nginx/反向代理.md"};function s(r,e,_,n,p,i){return t(),o("div",null,[...e[0]||(e[0]=[d('<div><p>服务器根据客户端的请求，从其关联的一组或多组后端<a href="https://baike.baidu.com/item/%E6%9C%8D%E5%8A%A1%E5%99%A8" target="_blank" rel="noreferrer">服务器</a>（如</p><p><code>Web</code></p><p>服务器）上获取资源，然后再将这些资源返回给客户端，客户端只会得知反向代理的<code>IP</code>地址，而不知道在代理服务器后面的服务器簇的存在<code>[1]</code>。 与前向代理不同，前向代理作为客户端的代理，将从互联网上获取的资源返回给一个或多个的客户端，服务端（如<code>Web</code>服务器）只知道代理的<code>IP</code>地址而不知道客户端的<code>IP</code>地址；而反向代理是作为服务器端（如<code>Web</code>服务器）的代理使用，而不是客户端。客户端借由前向代理可以间接访问很多不同互联网服务器（簇）的资源，而反向代理是供很多客户端都通过它间接访问不同后端服务器上的资源，而不需要知道这些后端服务器的存在，而以为所有资源都来自于这个反向代理服务器。</p></div>',1)])])}const m=a(c,[["render",s]]);export{f as __pageData,m as default};
